import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// --- Google Fonts Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900&display=swap`)
      .join("&")}`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---


export type EisenhowerMatrixProps = Record<string, any>;

// --- Components ---

const GridLine = ({
  vertical,
  thickness,
  color,
  progress,
  length
}: {
  vertical: boolean;
  thickness: number;
  color: string;
  progress: number;
  length: number;
}) => {
  const style: React.CSSProperties = {
    position: "absolute",
    backgroundColor: color,
    borderRadius: thickness / 2,
    opacity: Math.min(1, progress * 2), // Fade in quickly at start of growth
  };

  if (vertical) {
    Object.assign(style, {
      width: thickness,
      height: length,
      left: "50%",
      top: 0,
      transform: `translateX(-50%) scaleY(${progress})`,
      transformOrigin: "center",
    });
  } else {
    Object.assign(style, {
      height: thickness,
      width: length,
      top: "50%",
      left: 0,
      transform: `translateY(-50%) scaleX(${progress})`,
      transformOrigin: "center",
    });
  }

  return <div style={style} />;
};

const Quadrant = ({
  title,
  index,
  color,
  highlightColor,
  delayStart,
  fontSize,
}: {
  title: string;
  index: number;
  color: string;
  highlightColor: string;
  delayStart: number;
  fontSize: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Local frame time for this quadrant
  const localFrame = Math.max(0, frame - delayStart);

  // Text Reveal: Slide up and Fade in
  const slideProgress = spring({
    frame: localFrame,
    fps,
    config: { damping: 15, stiffness: 100 },
  });

  const textOpacity = interpolate(localFrame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const textTranslateY = interpolate(slideProgress, [0, 1], [30, 0]);

  // Flash Effect
  const flashOpacity = interpolate(
    localFrame,
    [0, 5, 40],
    [0, 0.25, 0.05], // Flash to 25%, settle at 5%
    { extrapolateRight: "clamp" }
  );

  const containerStyle: React.CSSProperties = {
    position: "absolute",
    width: "50%",
    height: "50%",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    left: index % 2 === 1 ? "50%" : 0, 
    top: index >= 2 ? "50%" : 0,
    overflow: "hidden", // Clip the highlight to the quadrant
  };

  // Adjust positioning based on specific quadrant mapping
  // Order: 0:TL, 1:TR, 2:BR, 3:BL (as per reveal order requested)
  // Mapping index to position:
  // 0 -> TL (left:0, top:0)
  // 1 -> TR (left:50%, top:0)
  // 2 -> BR (left:50%, top:50%)
  // 3 -> BL (left:0, top:50%)
  
  let left = "0%";
  let top = "0%";
  
  if (index === 0) { left = "0%"; top = "0%"; }
  if (index === 1) { left = "50%"; top = "0%"; }
  if (index === 2) { left = "50%"; top = "50%"; }
  if (index === 3) { left = "0%"; top = "50%"; }

  const computedContainerStyle = { ...containerStyle, left, top };

  return (
    <div style={computedContainerStyle}>
      {/* Highlight Flash Background */}
      <AbsoluteFill
        style={{
          backgroundColor: highlightColor,
          opacity: flashOpacity,
          borderRadius: 8, // slight soft edge
          transform: "scale(0.95)", // slightly smaller than full quadrant to leave gap near lines
        }}
      />
      
      {/* Title Text */}
      <div
        style={{
          fontFamily: "Playfair Display, serif",
          fontStyle: "italic",
          fontSize: fontSize,
          color: color,
          opacity: textOpacity,
          transform: `translateY(${textTranslateY}px)`,
          textAlign: "center",
          fontWeight: 600,
          zIndex: 10,
        }}
      >
        {title}
      </div>
    </div>
  );
};

const AxisLabel = ({
  text,
  position, // 'left-top', 'left-bottom', 'bottom-left', 'bottom-right'
  color,
  delay,
  fontSize,
}: {
  text: string;
  position: "left-top" | "left-bottom" | "bottom-left" | "bottom-right";
  color: string;
  delay: number;
  fontSize: number;
}) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame, [delay, delay + 20], [0, 1], { extrapolateRight: "clamp" });
  
  // Base offset from grid
  const offset = 40; 
  
  let style: React.CSSProperties = {
    position: "absolute",
    color: color,
    fontFamily: "Inter, sans-serif",
    fontSize: fontSize,
    fontWeight: 700,
    letterSpacing: "0.1em",
    opacity,
    whiteSpace: "nowrap",
    textTransform: "uppercase",
  };

  // Positioning logic relative to center
  if (position.startsWith("left")) {
    style.transform = "rotate(-90deg) translateX(-50%)"; // Center pivot correction for rotation
    style.transformOrigin = "center left";
    style.left = -offset * 1.5; // Push left outside grid
    style.textAlign = "center";
    
    // Vertical centering for the segments
    // left-top: center of top half -> 25% from top
    // left-bottom: center of bottom half -> 75% from top
    style.top = position === "left-top" ? "25%" : "75%";
    
    // Correction for the rotation anchor
    // When rotated -90, the width becomes height. We need to center it on the point.
    // Simpler: Use absolute positioning with transform centering.
    style = {
        ...style,
        left: -50, // Arbitrary offset
        width: 40, // Small width to force centering anchor? No, better to use transform.
        transform: "rotate(-90deg) translate(0, 50%)", // Rotate and align
        transformOrigin: "center center",
        textAlign: "center",
        // Reset top/left
    }
    
    // Manual positioning relative to grid container
    if (position === "left-top") {
        style.top = "25%";
        style.left = -60; // Approximate gap
        style.transform = "translate(-50%, -50%) rotate(-90deg)";
    } else {
        style.top = "75%";
        style.left = -60;
        style.transform = "translate(-50%, -50%) rotate(-90deg)";
    }

  } else {
    // Bottom labels
    style.bottom = -offset;
    style.transform = "translateX(-50%)";
    if (position === "bottom-left") {
        style.left = "25%";
    } else {
        style.left = "75%";
    }
  }

  return <div style={style}>{text}</div>;
};


// --- Main Composition ---

const EisenhowerMatrix: React.FC<EisenhowerMatrixProps> = ({
  backgroundColor = "#7c3aed",
  transparentBackground = false,
  lineColor = "#ffffff",
  textColor = "#ffffff",
  quadrantTextColor = "#ffffff",
  highlightColor = "#ffffff",
  gridThickness = 3,
  durationInSeconds = 10,
  // Font Sizes
  axisFontSize = 24,
  quadrantFontSize = 40,
  // Content
  axisVerticalTop = "Important",
  axisVerticalBottom = "Not Important",
  axisHorizontalLeft = "Urgent",
  axisHorizontalRight = "Not Urgent",
  q1TopLeftText = "Do",
  q2TopRightText = "Do Later",
  q3BottomRightText = "Delete",
  q4BottomLeftText = "Delegate",
}) => {
  useFontLoader(["Playfair Display", "Inter"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Layout Constants
  const minDim = Math.min(width, height);
  const gridSize = minDim * 0.6;
  
  // Animation Timing
  const gridStartFrame = 0;
  const axisStartFrame = 35;
  const quadrantStartFrame = 50;
  const quadrantStagger = 25; // Delay between each quadrant

  // Grid Animation
  const gridSpring = spring({
    frame: Math.max(0, frame - gridStartFrame),
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 60 },
    durationInFrames: 60,
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
      
      {/* Main Grid Container (Relative Pivot) */}
      <div
        style={{
          width: gridSize,
          height: gridSize,
          position: "relative",
        }}
      >
        
        {/* Axis Labels */}
        <AxisLabel 
            text={axisVerticalTop} position="left-top" 
            color={textColor} delay={axisStartFrame} 
            fontSize={axisFontSize}
        />
        <AxisLabel 
            text={axisVerticalBottom} position="left-bottom" 
            color={textColor} delay={axisStartFrame} 
            fontSize={axisFontSize}
        />
        <AxisLabel 
            text={axisHorizontalLeft} position="bottom-left" 
            color={textColor} delay={axisStartFrame} 
            fontSize={axisFontSize}
        />
        <AxisLabel 
            text={axisHorizontalRight} position="bottom-right" 
            color={textColor} delay={axisStartFrame} 
            fontSize={axisFontSize}
        />

        {/* Quadrant Contents */}
        {/* Order: TL -> TR -> BR -> BL (Clockwise from Top Left to match visual flow requested) */}
        {/* 
            Mapping:
            0 (TL): q1TopLeftText
            1 (TR): q2TopRightText
            2 (BR): q3BottomRightText
            3 (BL): q4BottomLeftText
         */}
        <Quadrant
          index={0} // TL
          title={q1TopLeftText}
          color={quadrantTextColor}
          highlightColor={highlightColor}
          delayStart={quadrantStartFrame}
          fontSize={quadrantFontSize}
        />
        <Quadrant
          index={1} // TR
          title={q2TopRightText}
          color={quadrantTextColor}
          highlightColor={highlightColor}
          delayStart={quadrantStartFrame + quadrantStagger}
          fontSize={quadrantFontSize}
        />
        <Quadrant
          index={2} // BR
          title={q3BottomRightText}
          color={quadrantTextColor}
          highlightColor={highlightColor}
          delayStart={quadrantStartFrame + (quadrantStagger * 2)}
          fontSize={quadrantFontSize}
        />
        <Quadrant
          index={3} // BL
          title={q4BottomLeftText}
          color={quadrantTextColor}
          highlightColor={highlightColor}
          delayStart={quadrantStartFrame + (quadrantStagger * 3)}
          fontSize={quadrantFontSize}
        />

        {/* Grid Lines (Rendered last to sit on top of highlights but maybe below text? Z-index handles text) */}
        <GridLine 
            vertical={true} 
            thickness={gridThickness} 
            color={lineColor} 
            progress={gridSpring} 
            length={gridSize} 
        />
        <GridLine 
            vertical={false} 
            thickness={gridThickness} 
            color={lineColor} 
            progress={gridSpring} 
            length={gridSize} 
        />
        
      </div>

    </AbsoluteFill>
  );
};

export default EisenhowerMatrix;